```javascript
// Function to call the company's web application API
async function callCompanyApi() {
    // Get user input (example: from a form or prompt)
    const userInput = prompt("Please enter your input:");

    // Validate input
    if (!userInput || userInput.trim() === "") {
        console.error("Input is required.");
        return;
    }

    // Define the API endpoint
    const apiUrl = "https://api.companywebapp.com/v1/endpoint"; // Replace with actual API URL

    // Prepare the request options
    const requestOptions = {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
            "Authorization": "Bearer YOUR_ACCESS_TOKEN" // Replace with actual auth if needed
        },
        body: JSON.stringify({
            input: userInput.trim()
        })
    };

    try {
        // Make the API call
        const response = await fetch(apiUrl, requestOptions);

        // Check if the response is OK (status in the range 200-299)
        if (!response.ok) {
            throw new Error(`API error: ${response.status} ${response.statusText}`);
        }

        // Parse the JSON response
        const data = await response.json();

        // Handle the successful response
        console.log("API Response:", data);
        alert("Success: " + JSON.stringify(data));
    } catch (error) {
        // Handle errors (network issues, API errors, etc.)
        console.error("Error calling API:", error);
        alert("An error occurred: " + error.message);
    }
}

// Call the function
callCompanyApi();
```

