### 🔐 `auth.js` – Secure Authentication Snippet

```javascript
// auth.js
const express = require('express');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const dotenv = require('dotenv');

dotenv.config();

const app = express();
app.use(express.json());

// Mock user storage (use a database like MongoDB or PostgreSQL in production)
const users = [];

const SECRET_KEY = process.env.JWT_SECRET || 'your-super-secret-jwt-key';

// ✅ Register Route
app.post('/register', async (req, res) => {
  const { username, password } = req.body;

  // Input validation
  if (!username || !password || username.length < 3 || password.length < 6) {
    return res.status(400).json({
      error: 'Username must be at least 3 characters and password at least 6 characters long.',
    });
  }

  // Check if user already exists
  const existingUser = users.find(u => u.username === username);
  if (existingUser) {
    return res.status(409).json({ error: 'Username already exists.' });
  }

  try {
    // Hash password
    const hashedPassword = await bcrypt.hash(password, 10);

    // Save user (in production, save to database)
    const user = { username, password: hashedPassword };
    users.push(user);

    console.log(`User registered: ${username}`);

    res.status(201).json({ message: 'User registered successfully.' });
  } catch (err) {
    res.status(500).json({ error: 'Registration failed.' });
  }
});

// ✅ Login Route
app.post('/login', async (req, res) => {
  const { username, password } = req.body;

  const user = users.find(u => u.username === username);
  if (!user) {
    return res.status(401).json({ error: 'Invalid username or password.' });
  }

  try {
    // Compare password
    const isMatch = await bcrypt.compare(password, user.password);
    if (!isMatch) {
      return res.status(401).json({ error: 'Invalid username or password.' });
    }

    // Create JWT token
    const token = jwt.sign({ username: user.username }, SECRET_KEY, {
      expiresIn: '1h',
    });

    // Optionally set as HTTP-only cookie (more secure)
    // res.cookie('token', token, { httpOnly: true, secure: true });

    res.json({ message: 'Login successful.', token });
  } catch (err) {
    res.status(500).json({ error: 'Login failed.' });
  }
});

// ✅ Protected Route Example
app.get('/profile', (req, res) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access denied. No token provided.' });
  }

  jwt.verify(token, SECRET_KEY, (err, decoded) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token.' });
    }
    res.json({ message: `Welcome ${decoded.username}`, profile: true });
  });
});

// Start server (for testing only)
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Auth server running on port ${PORT}`);
});
