### ✅ Backend Code (`server.js`)

```javascript
// server.js
const express = require('express');
const { createServer } = require('http');
const { WebSocketServer } = require('ws');

const app = express();
const server = createServer(app);
const wss = new WebSocketServer({ server });

// In-memory store for notes (use Redis or DB in production)
const notes = {};

// Broadcast a message to all connected clients
function broadcast(data) {
  const payload = JSON.stringify(data);
  wss.clients.forEach((client) => {
    if (client.readyState === client.OPEN) {
      client.send(payload);
    }
  });
}

// Handle WebSocket connections
wss.on('connection', (ws) => {
  console.log('Client connected');

  // Send current notes to the new client
  ws.send(JSON.stringify({ type: 'sync', notes }));

  // Handle incoming messages
  ws.on('message', (data) => {
    try {
      const message = JSON.parse(data);
      if (message.type === 'update' && message.id && message.content !== undefined) {
        notes[message.id] = message.content;
        // Broadcast update to all other clients
        broadcast({ type: 'update', id: message.id, content: message.content });
      }
    } catch (err) {
      console.error('Error parsing message:', err);
    }
  });

  ws.on('close', () => {
    console.log('Client disconnected');
  });
});

// Serve static files (HTML, JS, CSS)
app.use(express.static('public'));

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

