  <button onclick="addNote()">Add New Note</button>
  <div id="notes-container"></div>

  <script>
    // Connect to WebSocket server
    const ws = new WebSocket('ws://localhost:3000');

    const notesContainer = document.getElementById('notes-container');
    const notes = {};

    // Handle messages from server
    ws.onmessage = (event) => {
      const data = JSON.parse(event.data);

      if (data.type === 'sync') {
        // Sync all notes on connection
        Object.keys(data.notes).forEach(id => {
          notes[id] = data.notes[id];
        });
        renderNotes();
      } else if (data.type === 'update') {
        // Apply real-time update
        notes[data.id] = data.content;
        updateNoteElement(data.id, data.content);
      }
    };

    function addNote() {
      const id = 'note_' + Date.now();
      notes[id] = '';
      renderNotes();
      // Auto-focus new note
      setTimeout(() => {
        const textarea = document.getElementById(`note_${id}`);
        textarea.focus();
      }, 100);
    }

    function renderNotes() {
      notesContainer.innerHTML = '';
      Object.keys(notes).forEach(id => {
        const content = notes[id];
        const noteDiv = document.createElement('div');
        noteDiv.className = 'note';
        noteDiv.innerHTML = `
          <textarea id="note_${id}" placeholder="Write your note..." 
                    oninput="updateNote('${id}', this.value)">
            ${content}
          </textarea>`;
        notesContainer.appendChild(noteDiv);
      });
    }

    function updateNote(id, content) {
      notes[id] = content;
      // Send update to server
      ws.send(JSON.stringify({ type: 'update', id, content }));
    }

    function updateNoteElement(id, content) {
      const textarea = document.getElementById(`note_${id}`);
      if (textarea) textarea.value = content;
    }
  </script>
</body>
</html>
```

