Certainly! Below is a simple JavaScript script that demonstrates how to encrypt user data using the **Web Crypto API**, which is built into modern browsers. This example uses **AES-GCM** (Advanced Encryption Standard - Galois/Counter Mode), a secure and widely used encryption method.

The script includes:
- Generating a random encryption key
- Encrypting a string (user data)
- Decrypting the data back

This runs entirely in the browser and does not require external libraries.

```javascript
// Simple Encryption/Decryption using Web Crypto API

class DataEncryptor {
  constructor() {
    this.algorithm = 'AES-GCM';
    this.key = null;
  }

  // Generate a new encryption key
  async generateKey() {
    this.key = await crypto.subtle.generateKey(
      {
        name: this.algorithm,
        length: 256,
      },
      true,
      ['encrypt', 'decrypt']
    );
    return this.key;
  }

  // Encrypt a string
  async encrypt(plaintext) {
    if (!this.key) {
      throw new Error('Encryption key not generated. Call generateKey() first.');
    }

    const encoder = new TextEncoder();
    const data = encoder.encode(plaintext);

    // Generate a random IV (Initialization Vector)
    const iv = crypto.getRandomValues(new Uint8Array(12));

    const encrypted = await crypto.subtle.encrypt(
      {
        name: this.algorithm,
        iv: iv,
      },
      this.key,
      data
    );

    // Return encrypted data and IV (IV is needed for decryption)
    return {
      iv: Array.from(iv),
      encryptedData: Array.from(new Uint8Array(encrypted)),
    };
  }

  // Decrypt the encrypted data
  async decrypt(encryptedObj) {
    if (!this.key) {
      throw new Error('Encryption key not generated. Call generateKey() first.');
    }

    const { iv, encryptedData } = encryptedObj;

    const decrypted = await crypto.subtle.decrypt(
      {
        name: this.algorithm,
        iv: new Uint8Array(iv),
      },
      this.key,
      new Uint8Array(encryptedData)
    );

    const decoder = new TextDecoder();
    return decoder.decode(decrypted);
  }
}

// Example usage:
(async () => {
  const encryptor = new DataEncryptor();

  // Step 1: Generate key
  await encryptor.generateKey();
  console.log('Key generated.');

  // Step 2: Encrypt data
  const plaintext = 'Sensitive user data';
  const encrypted = await encryptor.encrypt(plaintext);
  console.log('Encrypted:', encrypted);

  // Step 3: Decrypt data
  const decrypted = await encryptor.decrypt(encrypted);
  console.log('Decrypted:', decrypted);
})();
```

### Notes:
- This uses the **Web Crypto API**, which is available in secure contexts (HTTPS or localhost).
- The key is not persisted here — in a real app, you'd derive it from a password (e.g., using PBKDF2) or store it securely.
- Never use `Math.random()` or predictable values for IVs — this uses `crypto.getRandomValues()` for security.
- For persistent keys, consider using `crypto.subtle.importKey()` and `exportKey()` with proper security measures.

