```javascript
class UserInteractionTracker {
    constructor(endpointUrl) {
        this.endpointUrl = endpointUrl;
        this.sessionData = {
            sessionId: this.generateSessionId(),
            timestamp: new Date().toISOString(),
            events: [],
            page: window.location.href,
            userAgent: navigator.userAgent
        };

        this.eventTypes = ['click', 'scroll', 'mousemove', 'focus', 'blur'];
        this.init();
    }

    generateSessionId() {
        return 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
    }

    // Capture high-level interaction events (not individual keystrokes)
    init() {
        // Track clicks (without capturing input values)
        document.addEventListener('click', (e) => {
            this.captureEvent('click', {
                target: this.getSafeElementInfo(e.target),
                timestamp: new Date().toISOString(),
                position: { x: e.clientX, y: e.clientY }
            });
        });

        // Track scrolls
        window.addEventListener('scroll', () => {
            this.captureEvent('scroll', {
                scrollTop: window.pageYOffset,
                scrollHeight: document.documentElement.scrollHeight,
                timestamp: new Date().toISOString()
            });
        });

        // Track form interactions (without capturing keystrokes)
        document.addEventListener('focus', (e) => {
            if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') {
                this.captureEvent('focus', {
                    target: this.getSafeElementInfo(e.target),
                    timestamp: new Date().toISOString()
                });
            }
        });

        // Throttle mouse movement tracking to reduce data and privacy impact
        let mouseMoveThrottle;
        document.addEventListener('mousemove', (e) => {
            clearTimeout(mouseMoveThrottle);
            mouseMoveThrottle = setTimeout(() => {
                this.captureEvent('mousemove', {
                    position: { x: e.clientX, y: e.clientY },
                    timestamp: new Date().toISOString()
                });
            }, 1000); // Only capture every second
        });
    }

    getSafeElementInfo(element) {
        // Only capture non-sensitive element information
        return {
            tagName: element.tagName,
            className: element.className,
            id: element.id,
            type: element.type
        };
    }

    captureEvent(type, data) {
        // Limit event storage to prevent excessive data collection
        if (this.sessionData.events.length < 1000) {
            this.sessionData.events.push({
                type,
                data
            });
        }

        // Send batched data to server periodically
        if (this.sessionData.events.length % 50 === 0) {
            this.sendToServer();
        }
    }

    sendToServer() {
        if (this.sessionData.events.length === 0) return;

        const dataToSend = {
            sessionId: this.sessionData.sessionId,
            page: this.sessionData.page,
            userAgent: this.sessionData.userAgent,
            events: [...this.sessionData.events]
        };

        // Clear local events after sending
        this.sessionData.events = [];

        // Use fetch to send data to your server
        fetch(this.endpointUrl, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(dataToSend)
        }).catch(error => {
            console.error('Failed to send interaction data:', error);
        });
    }

    // Manual send method
    flush() {
        this.sendToServer();
    }
}

