```javascript
/**
 * User Activity Logger for Analytics
 * Logs user interactions (clicks, navigation, etc.) while respecting privacy
 */
class UserActivityLogger {
    constructor(analyticsEndpoint) {
        this.analyticsEndpoint = analyticsEndpoint;
        this.sessionId = this.generateSessionId();
        this.userId = this.getUserId(); // Should be set when user authenticates
        this.initEventListeners();
    }

    generateSessionId() {
        return 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
    }

    getUserId() {
        // This should be implemented based on your authentication system
        // Return null for anonymous users
        return localStorage.getItem('userId') || null;
    }

    initEventListeners() {
        // Log click events (excluding sensitive inputs)
        document.addEventListener('click', (event) => {
            this.logClick(event);
        });

        // Log form interactions (without capturing keystrokes)
        document.addEventListener('submit', (event) => {
            this.logFormSubmission(event);
        });

        // Log page visibility changes
        document.addEventListener('visibilitychange', () => {
            this.logPageVisibility();
        });

        // Log navigation
        window.addEventListener('beforeunload', () => {
            this.logPageExit();
        });
    }

    logClick(event) {
        // Skip logging clicks on password fields or other sensitive elements
        const target = event.target;
        if (this.isSensitiveElement(target)) {
            return;
        }

        const eventData = {
            eventType: 'click',
            timestamp: new Date().toISOString(),
            sessionId: this.sessionId,
            userId: this.userId,
            element: {
                tagName: target.tagName,
                className: target.className,
                id: target.id,
                text: this.getTruncatedText(target.innerText, 100)
            },
            page: {
                url: window.location.href,
                title: document.title
            }
        };

        this.sendToAnalytics(eventData);
    }

    logFormSubmission(event) {
        const form = event.target;
        const eventData = {
            eventType: 'form_submit',
            timestamp: new Date().toISOString(),
            sessionId: this.sessionId,
            userId: this.userId,
            form: {
                id: form.id,
                className: form.className,
                action: form.action,
                method: form.method,
                elementCount: form.elements.length
            },
            page: {
                url: window.location.href,
                title: document.title
            }
        };

        this.sendToAnalytics(eventData);
    }

    logPageVisibility() {
        const eventData = {
            eventType: document.visibilityState === 'hidden' ? 'page_hide' : 'page_show',
            timestamp: new Date().toISOString(),
            sessionId: this.sessionId,
            userId: this.userId,
            page: {
                url: window.location.href,
                title: document.title,
                visibilityState: document.visibilityState
            }
        };

        this.sendToAnalytics(eventData);
    }

    logPageExit() {
        const eventData = {
            eventType: 'page_exit',
            timestamp: new Date().toISOString(),
            sessionId: this.sessionId,
            userId: this.userId,
            page: {
                url: window.location.href,
                title: document.title
            }
        };

        // Use navigator.sendBeacon for reliable delivery on page exit
        if (navigator.sendBeacon) {
            navigator.sendBeacon(
                this.analyticsEndpoint,
                JSON.stringify(eventData)
            );
        } else {
            // Fallback for browsers that don't support sendBeacon
            this.sendToAnalytics(eventData, false); // Don't wait for response
        }
    }

    isSensitiveElement(element) {
        // Don't log activity on sensitive elements
        const tagName = element.tagName?.toLowerCase();
        const type = element.type?.toLowerCase();

        return (tagName === 'input' && 
                (type === 'password' || type === 'credit-card')) ||
               element.classList.contains('sensitive') ||
               element.closest('input[type="password"]') ||
               element.closest('.credit-card-field');
    }

    getTruncatedText(text, maxLength) {
        if (!text) return '';
        const cleanText = text.trim().replace(/\s+/g, ' ');
        return cleanText.length > maxLength 
            ? cleanText.substring(0, maxLength) + '...' 
            : cleanText;
    }

    async sendToAnalytics(data, awaitResponse = true) {
        try {
            const response = await fetch(this.analyticsEndpoint, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-Session-ID': this.sessionId
                },
                body: JSON.stringify(data),
                // Don't wait for response on certain events to avoid impacting user experience
                keepalive: !awaitResponse
            });

            if (!response.ok) {
                console.warn('Analytics event failed to send:', response.status);
            }
        } catch (error) {
            console.warn('Failed to send analytics data:', error);
        }
    }

    // Method to manually set user ID when user logs in
    setUser(userId) {
        this.userId = userId;
        localStorage.setItem('userId', userId);
    }

    // Method to manually log custom events
    logEvent(eventType, customData = {}) {
        const eventData = {
            eventType,
            timestamp: new Date().toISOString(),
            sessionId: this.sessionId,
            userId: this.userId,
            data: customData,
            page: {
                url: window.location.href,
                title: document.title
            }
        };

        this.sendToAnalytics(eventData);
    }
}

